-- HANA PRE-FLIGHT for schema HACKFEST0119: can the 17 core tables be created here? Nothing is loaded.
-- Generated by `python -m backend.database.hana_core`, do not edit. Change hana_core_spec.py and regenerate.
--
-- This file has NO DROP, DELETE, TRUNCATE, ALTER or INSERT. It never replaces an object. NOT YET RUN ON A HANA TENANT.
-- Paste the WHOLE file into a SQL console connected to the Hackfest-DB instance and press Run All (F8). See HANA_PREFLIGHT_INSTRUCTIONS.md.
-- STEP 2 is the only part that changes anything, and it refuses to start if any of the 17 names already exists in HACKFEST0119.
-- Every name below is schema-qualified or filtered on HACKFEST0119, so the tables cannot land in another schema whatever the session schema is.

SET SCHEMA "HACKFEST0119";

-- ================================================================================================
-- STEP 1 (read only): who am I, does the schema exist, is any of the 17 names already taken?
-- ================================================================================================

-- 1a. EXPECTED: one row. TARGET_SCHEMA_EXISTS = 1. SESSION_SCHEMA = HACKFEST0119. TARGET_SCHEMA_OWNER shows who owns it and
-- USER_HAS_PRIVILEGES is TRUE when you own it or hold any privilege on it. (Whether you may CREATE there is only proved by STEP 2.)
SELECT CURRENT_USER AS CONNECTED_AS, CURRENT_SCHEMA AS SESSION_SCHEMA, 'HACKFEST0119' AS TARGET_SCHEMA,
       (SELECT COUNT(*) FROM SYS.SCHEMAS WHERE SCHEMA_NAME = 'HACKFEST0119') AS TARGET_SCHEMA_EXISTS,
       (SELECT MAX(SCHEMA_OWNER) FROM SYS.SCHEMAS WHERE SCHEMA_NAME = 'HACKFEST0119') AS TARGET_SCHEMA_OWNER,
       (SELECT MAX(HAS_PRIVILEGES) FROM SYS.SCHEMAS WHERE SCHEMA_NAME = 'HACKFEST0119') AS USER_HAS_PRIVILEGES
  FROM DUMMY;

-- 1b. EXPECTED: 17 rows, every STATUS = FREE. Any other STATUS means that name is taken and STEP 2 will refuse to create anything.
SELECT E.LOAD_ORDER, E.TABLE_NAME,
       CASE WHEN O.OBJECT_NAME IS NULL THEN 'FREE' ELSE 'ALREADY EXISTS (' || O.OBJECT_TYPE || ')' END AS STATUS
  FROM (
         SELECT 1 AS LOAD_ORDER, CAST('COUNTRY' AS NVARCHAR(128)) AS TABLE_NAME FROM DUMMY
         UNION ALL SELECT 2, 'PORT' FROM DUMMY
         UNION ALL SELECT 3, 'PRODUCT' FROM DUMMY
         UNION ALL SELECT 4, 'WAREHOUSE' FROM DUMMY
         UNION ALL SELECT 5, 'SUPPLIER' FROM DUMMY
         UNION ALL SELECT 6, 'SUPPLIER_PRODUCT' FROM DUMMY
         UNION ALL SELECT 7, 'ROUTE' FROM DUMMY
         UNION ALL SELECT 8, 'TARIFF' FROM DUMMY
         UNION ALL SELECT 9, 'DISRUPTION_EVENT' FROM DUMMY
         UNION ALL SELECT 10, 'DISRUPTION_IMPACT' FROM DUMMY
         UNION ALL SELECT 11, 'SCENARIO' FROM DUMMY
         UNION ALL SELECT 12, 'SCENARIO_STATE' FROM DUMMY
         UNION ALL SELECT 13, 'SCENARIO_PARAM' FROM DUMMY
         UNION ALL SELECT 14, 'INVENTORY_POLICY' FROM DUMMY
         UNION ALL SELECT 15, 'INVENTORY' FROM DUMMY
         UNION ALL SELECT 16, 'DEMAND' FROM DUMMY
         UNION ALL SELECT 17, 'DEMAND_MODELING_PANEL' FROM DUMMY
       ) E
  LEFT JOIN SYS.OBJECTS O ON O.SCHEMA_NAME = 'HACKFEST0119' AND O.OBJECT_NAME = E.TABLE_NAME
 ORDER BY E.LOAD_ORDER;

-- 1c. EXPECTED: one row starting with GO.
SELECT CASE WHEN COUNT(*) = 0
            THEN 'GO: all 17 names are free in HACKFEST0119, STEP 2 will create the tables'
            ELSE 'STOP: ' || TO_VARCHAR(COUNT(*)) || ' of the 17 names already exist in HACKFEST0119, STEP 2 will refuse to create anything'
       END AS PREFLIGHT_VERDICT
  FROM SYS.OBJECTS
 WHERE SCHEMA_NAME = 'HACKFEST0119' AND OBJECT_NAME IN ('COUNTRY', 'PORT', 'PRODUCT', 'WAREHOUSE', 'SUPPLIER', 'SUPPLIER_PRODUCT', 'ROUTE', 'TARIFF', 'DISRUPTION_EVENT', 'DISRUPTION_IMPACT', 'SCENARIO', 'SCENARIO_STATE', 'SCENARIO_PARAM', 'INVENTORY_POLICY', 'INVENTORY', 'DEMAND', 'DEMAND_MODELING_PANEL');

-- ================================================================================================
-- STEP 2 (creates the 17 tables, all or nothing at the gate): one anonymous block. Parents are created before children.
-- The gates raise error 10001 or 10002 BEFORE anything is created. Once past the gates a failure in a CREATE stops the block. HANA
-- normally commits DDL as it goes, so the tables before the failure may remain and STEP 3 shows which exist. Nothing is dropped or replaced.
-- EXPECTED: the console reports the statement as successfully executed and returns no rows.
-- ================================================================================================

DO BEGIN
    DECLARE v_found INTEGER;

    -- gate 1: the target schema must exist
    SELECT COUNT(*) INTO v_found FROM SYS.SCHEMAS WHERE SCHEMA_NAME = 'HACKFEST0119';
    IF :v_found = 0 THEN
        SIGNAL SQL_ERROR_CODE 10001 SET MESSAGE_TEXT = 'PRE-FLIGHT STOPPED: schema HACKFEST0119 does not exist. Nothing was created.';
    END IF;

    -- gate 2: none of the 17 names may be taken by any object
    SELECT COUNT(*) INTO v_found FROM SYS.OBJECTS WHERE SCHEMA_NAME = 'HACKFEST0119' AND OBJECT_NAME IN ('COUNTRY', 'PORT', 'PRODUCT', 'WAREHOUSE', 'SUPPLIER', 'SUPPLIER_PRODUCT', 'ROUTE', 'TARIFF', 'DISRUPTION_EVENT', 'DISRUPTION_IMPACT', 'SCENARIO', 'SCENARIO_STATE', 'SCENARIO_PARAM', 'INVENTORY_POLICY', 'INVENTORY', 'DEMAND', 'DEMAND_MODELING_PANEL');
    IF :v_found > 0 THEN
        SIGNAL SQL_ERROR_CODE 10002 SET MESSAGE_TEXT = 'PRE-FLIGHT STOPPED: one or more of the 17 table names already exist in HACKFEST0119. Nothing was created, dropped or replaced. Run STEP 1 to see which.';
    END IF;

    -- 1 of 17: COUNTRY
    EXEC 'CREATE COLUMN TABLE "HACKFEST0119"."COUNTRY" (
    "ISO3" NVARCHAR(3) NOT NULL,
    "ISO2" NVARCHAR(2),
    "NAME" NVARCHAR(100) NOT NULL,
    "REGION" NVARCHAR(64) NOT NULL,
    "INCOME_GROUP" NVARCHAR(32) NOT NULL,
    "RETAIL_LABEL" NVARCHAR(64),
    "PROVENANCE" NVARCHAR(12) NOT NULL,
    CONSTRAINT "PK_COUNTRY" PRIMARY KEY ("ISO3"),
    CONSTRAINT "CK_COUNTRY_PROVENANCE" CHECK ("PROVENANCE" IN (''REAL'', ''DERIVED'', ''SYNTHETIC'', ''AUTHORED''))
)';

    -- 2 of 17: PORT
    EXEC 'CREATE COLUMN TABLE "HACKFEST0119"."PORT" (
    "PORT_ID" INTEGER NOT NULL,
    "PORT_NAME" NVARCHAR(128) NOT NULL,
    "COUNTRY_ISO2" NVARCHAR(2) NOT NULL,
    "COUNTRY_ISO3" NVARCHAR(3),
    "LATITUDE" DECIMAL(9,6) NOT NULL,
    "LONGITUDE" DECIMAL(9,6) NOT NULL,
    "HARBOR_SIZE" NVARCHAR(1),
    "HARBOR_TYPE" NVARCHAR(2),
    "SOURCE" NVARCHAR(256) NOT NULL,
    "PROVENANCE" NVARCHAR(12) NOT NULL,
    CONSTRAINT "PK_PORT" PRIMARY KEY ("PORT_ID"),
    CONSTRAINT "FK_PORT_COUNTRY" FOREIGN KEY ("COUNTRY_ISO3") REFERENCES "HACKFEST0119"."COUNTRY" ("ISO3"),
    CONSTRAINT "CK_PORT_PROVENANCE" CHECK ("PROVENANCE" IN (''REAL'', ''DERIVED'', ''SYNTHETIC'', ''AUTHORED'')),
    CONSTRAINT "CK_PORT_LATITUDE" CHECK ("LATITUDE" BETWEEN -90 AND 90),
    CONSTRAINT "CK_PORT_LONGITUDE" CHECK ("LONGITUDE" BETWEEN -180 AND 180)
)';

    -- 3 of 17: PRODUCT
    EXEC 'CREATE COLUMN TABLE "HACKFEST0119"."PRODUCT" (
    "PRODUCT_ID" NVARCHAR(32) NOT NULL,
    "PRODUCT_NAME" NVARCHAR(200) NOT NULL,
    "AVG_UNIT_PRICE_GBP" DOUBLE,
    "ABC_CLASS" NVARCHAR(1) NOT NULL,
    "NET_UNITS" INTEGER NOT NULL,
    "NET_REVENUE_GBP" DECIMAL(16,4) NOT NULL,
    "ACTIVE_DAYS" INTEGER NOT NULL,
    "FIRST_SALE_DATE" DATE,
    "LAST_SALE_DATE" DATE,
    "IS_FORECAST_SERIES" BOOLEAN NOT NULL,
    "PROVENANCE" NVARCHAR(12) NOT NULL,
    CONSTRAINT "PK_PRODUCT" PRIMARY KEY ("PRODUCT_ID"),
    CONSTRAINT "CK_PRODUCT_PROVENANCE" CHECK ("PROVENANCE" IN (''REAL'', ''DERIVED'', ''SYNTHETIC'', ''AUTHORED'')),
    CONSTRAINT "CK_PRODUCT_ABC_CLASS" CHECK ("ABC_CLASS" IN (''A'', ''B'', ''C'')),
    CONSTRAINT "CK_PRODUCT_NET_UNITS" CHECK ("NET_UNITS" >= 0),
    CONSTRAINT "CK_PRODUCT_NET_REVENUE" CHECK ("NET_REVENUE_GBP" >= 0),
    CONSTRAINT "CK_PRODUCT_ACTIVE_DAYS" CHECK ("ACTIVE_DAYS" >= 0),
    CONSTRAINT "CK_PRODUCT_SALE_DATES" CHECK ("FIRST_SALE_DATE" IS NULL OR "LAST_SALE_DATE" IS NULL OR "FIRST_SALE_DATE" <= "LAST_SALE_DATE")
)';

    -- 4 of 17: WAREHOUSE
    EXEC 'CREATE COLUMN TABLE "HACKFEST0119"."WAREHOUSE" (
    "WAREHOUSE_ID" NVARCHAR(32) NOT NULL,
