    "OUTBOUND_QUANTITY" INTEGER NOT NULL,
    "CLOSING_STOCK" INTEGER NOT NULL,
    "SAFETY_STOCK" INTEGER NOT NULL,
    "REORDER_POINT" INTEGER NOT NULL,
    "DEMAND_QUANTITY" INTEGER NOT NULL,
    "UNFILLED_QUANTITY" INTEGER NOT NULL,
    "STOCKOUT_FLAG" BOOLEAN NOT NULL,
    "PROVENANCE" NVARCHAR(12) NOT NULL,
    CONSTRAINT "PK_INVENTORY" PRIMARY KEY ("WAREHOUSE_ID", "PRODUCT_ID", "DATE"),
    CONSTRAINT "FK_INVENTORY_WAREHOUSE" FOREIGN KEY ("WAREHOUSE_ID") REFERENCES "HACKFEST0119"."WAREHOUSE" ("WAREHOUSE_ID"),
    CONSTRAINT "FK_INVENTORY_PRODUCT" FOREIGN KEY ("PRODUCT_ID") REFERENCES "HACKFEST0119"."PRODUCT" ("PRODUCT_ID"),
    CONSTRAINT "CK_INVENTORY_PROVENANCE" CHECK ("PROVENANCE" IN (''REAL'', ''DERIVED'', ''SYNTHETIC'', ''AUTHORED'')),
    CONSTRAINT "CK_INVENTORY_QUANTITIES" CHECK ("OPENING_STOCK" >= 0 AND "INBOUND_QUANTITY" >= 0 AND "OUTBOUND_QUANTITY" >= 0 AND "CLOSING_STOCK" >= 0 AND "SAFETY_STOCK" >= 0 AND "REORDER_POINT" >= 0 AND "DEMAND_QUANTITY" >= 0 AND "UNFILLED_QUANTITY" >= 0)
)';

    -- 16 of 17: DEMAND
    EXEC 'CREATE COLUMN TABLE "HACKFEST0119"."DEMAND" (
    "DATE" DATE NOT NULL,
    "PRODUCT_ID" NVARCHAR(32) NOT NULL,
    "LOCATION_ID" NVARCHAR(64) NOT NULL,
    "COUNTRY_ISO3" NVARCHAR(3) NOT NULL,
    "DEMAND_QUANTITY" INTEGER NOT NULL,
    "N_ORDER_LINES" INTEGER NOT NULL,
    "N_OUTLIER_LINES" INTEGER NOT NULL,
    "PROVENANCE" NVARCHAR(12) NOT NULL,
    CONSTRAINT "PK_DEMAND" PRIMARY KEY ("DATE", "PRODUCT_ID", "LOCATION_ID"),
    CONSTRAINT "FK_DEMAND_PRODUCT" FOREIGN KEY ("PRODUCT_ID") REFERENCES "HACKFEST0119"."PRODUCT" ("PRODUCT_ID"),
    CONSTRAINT "FK_DEMAND_COUNTRY" FOREIGN KEY ("COUNTRY_ISO3") REFERENCES "HACKFEST0119"."COUNTRY" ("ISO3"),
    CONSTRAINT "CK_DEMAND_PROVENANCE" CHECK ("PROVENANCE" IN (''REAL'', ''DERIVED'', ''SYNTHETIC'', ''AUTHORED'')),
    CONSTRAINT "CK_DEMAND_QUANTITY" CHECK ("DEMAND_QUANTITY" > 0),
    CONSTRAINT "CK_DEMAND_LINES" CHECK ("N_ORDER_LINES" > 0 AND "N_OUTLIER_LINES" >= 0)
)';

    -- 17 of 17: DEMAND_MODELING_PANEL
    EXEC 'CREATE COLUMN TABLE "HACKFEST0119"."DEMAND_MODELING_PANEL" (
    "DATE" DATE NOT NULL,
    "PRODUCT_ID" NVARCHAR(32) NOT NULL,
    "LOCATION_ID" NVARCHAR(64) NOT NULL,
    "DEMAND_QUANTITY" INTEGER NOT NULL,
    "LAG_1" DOUBLE,
    "LAG_2" DOUBLE,
    "LAG_7" DOUBLE,
    "LAG_14" DOUBLE,
    "LAG_28" DOUBLE,
    "ROLLING_MEAN_7" DOUBLE,
    "ROLLING_MEAN_14" DOUBLE,
    "ROLLING_MEAN_28" DOUBLE,
    "DAY_OF_WEEK" INTEGER NOT NULL,
    "MONTH" INTEGER NOT NULL,
    "DISRUPTION_ACTIVE" BOOLEAN NOT NULL,
    "SPLIT" NVARCHAR(8) NOT NULL,
    "HAS_OUTLIER_LINE" BOOLEAN NOT NULL,
    "PROVENANCE" NVARCHAR(12) NOT NULL,
    CONSTRAINT "PK_DEMAND_MODELING_PANEL" PRIMARY KEY ("DATE", "PRODUCT_ID", "LOCATION_ID"),
    CONSTRAINT "FK_DEMAND_MODELING_PANEL_PRODUCT" FOREIGN KEY ("PRODUCT_ID") REFERENCES "HACKFEST0119"."PRODUCT" ("PRODUCT_ID"),
    CONSTRAINT "CK_DEMAND_MODELING_PANEL_PROVENANCE" CHECK ("PROVENANCE" IN (''REAL'', ''DERIVED'', ''SYNTHETIC'', ''AUTHORED'')),
    CONSTRAINT "CK_DEMAND_MODELING_PANEL_QUANTITY" CHECK ("DEMAND_QUANTITY" >= 0),
    CONSTRAINT "CK_DEMAND_MODELING_PANEL_DAY_OF_WEEK" CHECK ("DAY_OF_WEEK" BETWEEN 0 AND 6),
    CONSTRAINT "CK_DEMAND_MODELING_PANEL_MONTH" CHECK ("MONTH" BETWEEN 1 AND 12),
    CONSTRAINT "CK_DEMAND_MODELING_PANEL_SPLIT" CHECK ("SPLIT" IN (''train'', ''val'', ''test''))
)';
END;

-- ================================================================================================
-- STEP 3 (read only): did the 17 tables come out as specified? Safe to run at any time, also after a failed STEP 2.
-- ================================================================================================

-- 3a. EXPECTED: 17 rows, every OUTCOME = OK. After a failed STEP 2 the first MISSING row is the table that failed.
SELECT E.LOAD_ORDER, E.TABLE_NAME, E.EXPECTED_COLUMNS, COUNT(C.COLUMN_NAME) AS ACTUAL_COLUMNS,
       CASE WHEN COUNT(C.COLUMN_NAME) = E.EXPECTED_COLUMNS THEN 'OK' WHEN COUNT(C.COLUMN_NAME) = 0 THEN 'MISSING' ELSE 'MISMATCH' END AS OUTCOME
  FROM (
         SELECT 1 AS LOAD_ORDER, CAST('COUNTRY' AS NVARCHAR(128)) AS TABLE_NAME, 7 AS EXPECTED_COLUMNS FROM DUMMY
         UNION ALL SELECT 2, 'PORT', 10 FROM DUMMY
         UNION ALL SELECT 3, 'PRODUCT', 11 FROM DUMMY
         UNION ALL SELECT 4, 'WAREHOUSE', 6 FROM DUMMY
         UNION ALL SELECT 5, 'SUPPLIER', 8 FROM DUMMY
         UNION ALL SELECT 6, 'SUPPLIER_PRODUCT', 7 FROM DUMMY
         UNION ALL SELECT 7, 'ROUTE', 17 FROM DUMMY
         UNION ALL SELECT 8, 'TARIFF', 9 FROM DUMMY
         UNION ALL SELECT 9, 'DISRUPTION_EVENT', 11 FROM DUMMY
         UNION ALL SELECT 10, 'DISRUPTION_IMPACT', 7 FROM DUMMY
         UNION ALL SELECT 11, 'SCENARIO', 8 FROM DUMMY
         UNION ALL SELECT 12, 'SCENARIO_STATE', 7 FROM DUMMY
         UNION ALL SELECT 13, 'SCENARIO_PARAM', 8 FROM DUMMY
         UNION ALL SELECT 14, 'INVENTORY_POLICY', 9 FROM DUMMY
         UNION ALL SELECT 15, 'INVENTORY', 13 FROM DUMMY
         UNION ALL SELECT 16, 'DEMAND', 8 FROM DUMMY
         UNION ALL SELECT 17, 'DEMAND_MODELING_PANEL', 18 FROM DUMMY
       ) E
  LEFT JOIN SYS.TABLE_COLUMNS C ON C.SCHEMA_NAME = 'HACKFEST0119' AND C.TABLE_NAME = E.TABLE_NAME
 GROUP BY E.LOAD_ORDER, E.TABLE_NAME, E.EXPECTED_COLUMNS
 ORDER BY E.LOAD_ORDER;

-- 3b. EXPECTED: 4 rows, every OUTCOME = OK (17 column tables, 17 tables with a primary key, 20 foreign keys, 60 CHECK constraints).
SELECT V.CHECK_NAME, V.ACTUAL, V.EXPECTED, CASE WHEN V.ACTUAL = V.EXPECTED THEN 'OK' ELSE 'MISMATCH' END AS OUTCOME
  FROM (
         SELECT CAST('column tables' AS NVARCHAR(64)) AS CHECK_NAME,
                (SELECT COUNT(*) FROM SYS.TABLES WHERE SCHEMA_NAME = 'HACKFEST0119' AND TABLE_NAME IN ('COUNTRY', 'PORT', 'PRODUCT', 'WAREHOUSE', 'SUPPLIER', 'SUPPLIER_PRODUCT', 'ROUTE', 'TARIFF', 'DISRUPTION_EVENT', 'DISRUPTION_IMPACT', 'SCENARIO', 'SCENARIO_STATE', 'SCENARIO_PARAM', 'INVENTORY_POLICY', 'INVENTORY', 'DEMAND', 'DEMAND_MODELING_PANEL') AND IS_COLUMN_TABLE = 'TRUE') AS ACTUAL,
                17 AS EXPECTED FROM DUMMY
         UNION ALL SELECT 'tables with a primary key',
                (SELECT COUNT(DISTINCT TABLE_NAME) FROM SYS.CONSTRAINTS WHERE SCHEMA_NAME = 'HACKFEST0119' AND TABLE_NAME IN ('COUNTRY', 'PORT', 'PRODUCT', 'WAREHOUSE', 'SUPPLIER', 'SUPPLIER_PRODUCT', 'ROUTE', 'TARIFF', 'DISRUPTION_EVENT', 'DISRUPTION_IMPACT', 'SCENARIO', 'SCENARIO_STATE', 'SCENARIO_PARAM', 'INVENTORY_POLICY', 'INVENTORY', 'DEMAND', 'DEMAND_MODELING_PANEL') AND IS_PRIMARY_KEY = 'TRUE'),
                17 FROM DUMMY
         UNION ALL SELECT 'foreign keys',
                (SELECT COUNT(DISTINCT CONSTRAINT_NAME) FROM SYS.REFERENTIAL_CONSTRAINTS WHERE SCHEMA_NAME = 'HACKFEST0119' AND TABLE_NAME IN ('COUNTRY', 'PORT', 'PRODUCT', 'WAREHOUSE', 'SUPPLIER', 'SUPPLIER_PRODUCT', 'ROUTE', 'TARIFF', 'DISRUPTION_EVENT', 'DISRUPTION_IMPACT', 'SCENARIO', 'SCENARIO_STATE', 'SCENARIO_PARAM', 'INVENTORY_POLICY', 'INVENTORY', 'DEMAND', 'DEMAND_MODELING_PANEL')),
                20 FROM DUMMY
         UNION ALL SELECT 'check constraints',
                (SELECT COUNT(DISTINCT CONSTRAINT_NAME) FROM SYS.CONSTRAINTS WHERE SCHEMA_NAME = 'HACKFEST0119' AND TABLE_NAME IN ('COUNTRY', 'PORT', 'PRODUCT', 'WAREHOUSE', 'SUPPLIER', 'SUPPLIER_PRODUCT', 'ROUTE', 'TARIFF', 'DISRUPTION_EVENT', 'DISRUPTION_IMPACT', 'SCENARIO', 'SCENARIO_STATE', 'SCENARIO_PARAM', 'INVENTORY_POLICY', 'INVENTORY', 'DEMAND', 'DEMAND_MODELING_PANEL') AND CHECK_CONDITION IS NOT NULL),
                60 FROM DUMMY
       ) V;

-- 3c. EXPECTED: every OUTCOME = OK. Every DECIMAL keeps its precision and scale, every DOUBLE is DOUBLE (TARIFF_RATE_PCT included),
-- and CAPACITY is an INTEGER on SUPPLIER_PRODUCT and ROUTE. If only the ACTUAL_TYPE spelling differs, compare the two columns by eye.
SELECT E.TABLE_NAME, E.COLUMN_NAME, E.EXPECTED_TYPE,
       C.DATA_TYPE_NAME || CASE WHEN C.DATA_TYPE_NAME = 'DECIMAL' THEN '(' || TO_VARCHAR(C.LENGTH) || ',' || TO_VARCHAR(C.SCALE) || ')' ELSE '' END AS ACTUAL_TYPE,
       CASE WHEN C.COLUMN_NAME IS NULL THEN 'MISSING'
            WHEN C.DATA_TYPE_NAME || CASE WHEN C.DATA_TYPE_NAME = 'DECIMAL' THEN '(' || TO_VARCHAR(C.LENGTH) || ',' || TO_VARCHAR(C.SCALE) || ')' ELSE '' END = E.EXPECTED_TYPE THEN 'OK'
            ELSE 'MISMATCH' END AS OUTCOME
  FROM (
         SELECT CAST('PORT' AS NVARCHAR(128)) AS TABLE_NAME, CAST('LATITUDE' AS NVARCHAR(128)) AS COLUMN_NAME, CAST('DECIMAL(9,6)' AS NVARCHAR(128)) AS EXPECTED_TYPE FROM DUMMY
         UNION ALL SELECT 'PORT', 'LONGITUDE', 'DECIMAL(9,6)' FROM DUMMY
         UNION ALL SELECT 'PRODUCT', 'AVG_UNIT_PRICE_GBP', 'DOUBLE' FROM DUMMY
         UNION ALL SELECT 'PRODUCT', 'NET_REVENUE_GBP', 'DECIMAL(16,4)' FROM DUMMY
         UNION ALL SELECT 'SUPPLIER_PRODUCT', 'CAPACITY', 'INTEGER' FROM DUMMY
         UNION ALL SELECT 'SUPPLIER_PRODUCT', 'UNIT_COST', 'DECIMAL(16,4)' FROM DUMMY
         UNION ALL SELECT 'SUPPLIER_PRODUCT', 'RELIABILITY', 'DECIMAL(5,4)' FROM DUMMY
         UNION ALL SELECT 'ROUTE', 'DISTANCE_KM', 'DECIMAL(10,2)' FROM DUMMY
         UNION ALL SELECT 'ROUTE', 'LEGACY_DISTANCE_KM', 'DECIMAL(10,2)' FROM DUMMY
         UNION ALL SELECT 'ROUTE', 'CAPACITY', 'INTEGER' FROM DUMMY
         UNION ALL SELECT 'ROUTE', 'TRANSIT_TIME_DAYS', 'DECIMAL(8,2)' FROM DUMMY
         UNION ALL SELECT 'ROUTE', 'COST_PER_UNIT', 'DECIMAL(16,4)' FROM DUMMY
         UNION ALL SELECT 'TARIFF', 'TARIFF_RATE_PCT', 'DOUBLE' FROM DUMMY
         UNION ALL SELECT 'DISRUPTION_EVENT', 'ESTIMATED_DELAY_DAYS', 'DECIMAL(8,2)' FROM DUMMY
         UNION ALL SELECT 'DISRUPTION_IMPACT', 'DELAY_DAYS', 'DECIMAL(8,2)' FROM DUMMY
         UNION ALL SELECT 'DISRUPTION_IMPACT', 'CAPACITY_FACTOR', 'DECIMAL(5,4)' FROM DUMMY
         UNION ALL SELECT 'SCENARIO_STATE', 'CAPACITY_FACTOR', 'DECIMAL(5,4)' FROM DUMMY
         UNION ALL SELECT 'SCENARIO_PARAM', 'PARAM_VALUE', 'DECIMAL(14,4)' FROM DUMMY
         UNION ALL SELECT 'INVENTORY_POLICY', 'DEMAND_SHARE', 'DECIMAL(5,4)' FROM DUMMY
         UNION ALL SELECT 'INVENTORY_POLICY', 'COVER_MULTIPLIER', 'DECIMAL(6,4)' FROM DUMMY
         UNION ALL SELECT 'INVENTORY_POLICY', 'SAFETY_MULTIPLIER', 'DECIMAL(6,4)' FROM DUMMY
         UNION ALL SELECT 'DEMAND_MODELING_PANEL', 'LAG_1', 'DOUBLE' FROM DUMMY
         UNION ALL SELECT 'DEMAND_MODELING_PANEL', 'LAG_2', 'DOUBLE' FROM DUMMY
         UNION ALL SELECT 'DEMAND_MODELING_PANEL', 'LAG_7', 'DOUBLE' FROM DUMMY
         UNION ALL SELECT 'DEMAND_MODELING_PANEL', 'LAG_14', 'DOUBLE' FROM DUMMY
         UNION ALL SELECT 'DEMAND_MODELING_PANEL', 'LAG_28', 'DOUBLE' FROM DUMMY
         UNION ALL SELECT 'DEMAND_MODELING_PANEL', 'ROLLING_MEAN_7', 'DOUBLE' FROM DUMMY
         UNION ALL SELECT 'DEMAND_MODELING_PANEL', 'ROLLING_MEAN_14', 'DOUBLE' FROM DUMMY
         UNION ALL SELECT 'DEMAND_MODELING_PANEL', 'ROLLING_MEAN_28', 'DOUBLE' FROM DUMMY
       ) E
  LEFT JOIN SYS.TABLE_COLUMNS C ON C.SCHEMA_NAME = 'HACKFEST0119' AND C.TABLE_NAME = E.TABLE_NAME AND C.COLUMN_NAME = E.COLUMN_NAME
 ORDER BY E.TABLE_NAME, E.COLUMN_NAME;
